import sys
from pathlib import Path

M = 65536
lines = Path(sys.argv[1]).read_text().splitlines()
prog = []
for raw in lines:
    code = raw.split(";", 1)[0].strip()
    if code:
        prog.append(code.split())

regs = {"a": 0, "b": 0, "c": 0, "d": 0}

def val(tok):
    return regs[tok] if tok in regs else int(tok)

out_vals = []
count = 0
pc = 0
while 0 <= pc < len(prog):
    op, *args = prog[pc]
    count += 1
    nxt = pc + 1
    if op == "set":
        regs[args[0]] = val(args[1]) % M
    elif op == "add":
        regs[args[0]] = (regs[args[0]] + val(args[1])) % M
    elif op == "mul":
        regs[args[0]] = (regs[args[0]] * val(args[1])) % M
    elif op == "mod":
        y = val(args[1])
        if y > 0:
            regs[args[0]] = regs[args[0]] % y
    elif op == "dec":
        regs[args[0]] = max(0, regs[args[0]] - 1)
    elif op == "jnz":
        if val(args[0]) != 0:
            nxt = pc + val(args[1])
    elif op == "skp":
        if val(args[0]) < val(args[1]):
            count_skip = True
            nxt = pc + 2
    elif op == "out":
        out_vals.append(val(args[0]))
    else:
        raise SystemExit(f"unknown op {op} at {pc}")
    pc = nxt

print("outputs:", len(out_vals), "sum:", sum(out_vals))
print("executed:", count)
print("final regs:", regs)
print(f"{sum(out_vals)} {count}")
EOF
